DROP TABLE IF EXISTS `whatsapp_messages`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `whatsapp_messages` (
  `id` varchar(191) NOT NULL,
  `customer_id` varchar(191) DEFAULT NULL,
  `sale_id` varchar(191) DEFAULT NULL,
  `phone` varchar(191) NOT NULL,
  `message` varchar(191) NOT NULL,
  `status` enum('PENDING','SENT','FAILED') NOT NULL DEFAULT 'PENDING',
  `provider_message_id` varchar(191) DEFAULT NULL,
  `error_message` varchar(191) DEFAULT NULL,
  `sent_at` datetime(3) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  PRIMARY KEY (`id`),
  KEY `whatsapp_messages_customer_id_idx` (`customer_id`),
  KEY `whatsapp_messages_sale_id_idx` (`sale_id`),
  KEY `whatsapp_messages_status_idx` (`status`),
  KEY `whatsapp_messages_phone_idx` (`phone`),
  KEY `whatsapp_messages_created_at_idx` (`created_at`),
  CONSTRAINT `whatsapp_messages_customer_id_fkey` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `whatsapp_messages_sale_id_fkey` FOREIGN KEY (`sale_id`) REFERENCES `sales` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

